package edu.pe.cibertec.saibm.inventario.infrastructure.config; import org.springframework.context.annotation.*; import org.springframework.scheduling.annotation.EnableScheduling; import edu.pe.cibertec.saibm.inventario.application.port.in.InventoryUseCase; import edu.pe.cibertec.saibm.inventario.application.port.out.InventoryStorePort; import edu.pe.cibertec.saibm.inventario.application.usecase.InventoryService; @Configuration @EnableScheduling public class InventarioConfig { @Bean InventoryService inventoryService(InventoryStorePort store){return new InventoryService(store);} @Bean @Primary InventoryUseCase inventory(InventoryService service){return new InventoryTransactionalFacade(service);} }
